const frameLayoutLabel = (mode: FrameLayoutMode) => {
  if (mode === "row") {
    return "水平行布局";
  }
  if (mode === "column") {
    return "垂直列布局";
  }
  if (mode === "grid") {
    return "网格布局";
  }
  return "自由布局";
};
